import { useEditorSelector } from "platejs/react";
import { someList } from "@platejs/list-classic";

/**
 * Subscribe to whether the current selection is inside a specific list type.
 *
 * Must be used inside a `<RichText>` (or `<Plate>`) context.
 * Requires `@platejs/list-classic` to be installed.
 *
 * @param listPluginKey - The list plugin key (e.g., `BulletedListPlugin.key`, `NumberedListPlugin.key`)
 * @param editorId - Optional editor ID when multiple editors exist under a `PlateController`
 * @returns `true` if the current selection is inside the specified list type
 *
 * @example
 * const isBulleted = useListState(BulletedListPlugin.key);
 * const isNumbered = useListState(NumberedListPlugin.key);
 */
export function useListState(listPluginKey: string, editorId?: string): boolean {
  return useEditorSelector(
    (ed) => {
      if (!ed || !ed.selection) return false;
      return someList(ed, listPluginKey);
    },
    [],
    ...(editorId ? [{ id: editorId }] : []),
  );
}
